import { Box, Typography } from "@mui/material";
import LinkIcon from "@mui/icons-material/Link";
import React, { useContext, useEffect, useState } from "react";
import { ProjectContext } from "../providers/ProjectProvider";
import projectData from "../data/projectData";

function ProjectSideDetails() {
  const { boxes, activeBox, setOpenProject } = useContext(ProjectContext);
  const [animation, setAnimation] = useState(false);

  useEffect(() => {
    setAnimation(false);
    const timeOut = setTimeout(() => {
      setAnimation(true);
    }, 500);

    return () => clearTimeout(timeOut);
  }, [activeBox]);

  return (
    <Box
      sx={{
        flexGrow: "1",
        display: {md: "flex", xs: "none"},
        width: "400px",
        height: "auto",
        aspectRatio: "4 / 5", 
        bgcolor: "primary.main",
        marginLeft: "20px",
        marginY: "auto",
        borderRadius: "10px",
        boxSizing: "border-box",
        padding: "8px",
        flexDirection: "column",
        zIndex: "100",
      }}
    >
      <Box sx={{ display: "flex" }}>
        <Box
          component={"img"}
          src={boxes[activeBox].projectImg}
          sx={{
            height: "80px",
            width: "80px",
            borderRadius: "80px",
            bgcolor: "white",
            objectFit: "contain",
            transition: "opacity .5s ease",
            opacity: animation ? 1 : 0,
          }}
        />
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            marginLeft: "10px",
            justifyContent: "center",
            textAlign: "start",
          }}
        >
          <Typography
            sx={{
              fontFamily: "Lato, sans-serif",
              color: "white",
              fontWeight: "750",
              fontSize: "25px",
              lineHeight: "25px",
              transition: "transform 0.5s ease-in, opacity 0.5s",
              opacity: animation ? 1 : 0,
              transform: animation ? "translateX(0px)" : "translateX(20px)",
            }}
          >
            {boxes[activeBox].text}
          </Typography>
          <Box sx={{ display: "flex" }}>
            <Typography
              sx={{
                fontFamily: "Lato, sans-serif",
                color: "white",
                fontWeight: "750",
                fontSize: "17px",
              }}
            >
              GitHub
            </Typography>
            <a href={projectData[boxes[activeBox].id].githubUrl}>
              <LinkIcon sx={{ color: "#00ff00", fontSize: "25px", marginLeft: "3px", cursor: "pointer", zIndex: "101" }} />
            </a>
          </Box>
        </Box>
      </Box>
      <Box
        sx={{
          display: "grid",
          flex: "1",
          marginTop: "10px",
          gridTemplateColumns: "1fr 1fr",
          gridTemplateRows: "repeat(7, 1fr)",
          gap: "5px",
        }}
      >
        <Box
          sx={{
            gridRow: "span 7",
            borderRadius: "15px",
            background: `url(${projectData[boxes[activeBox].id].images[0]})`,
            backgroundSize: "cover",
            transition: "transform 0.3s linear",
            transform: animation ? "translateX(0px)" : "translateX(20px)",
          }}
        />
        <Box
          sx={{
            gridRow: "span 3",
            borderRadius: "15px",
            background: `url(${projectData[boxes[activeBox].id].images[1]})`,
            backgroundSize: "cover",
            transition: "transform 0.4s linear",
            transform: animation ? "translateX(0px)" : "translateX(20px)",
          }}
        />
        <Box
          sx={{
            gridRow: "span 3",
            borderRadius: "15px",
            background: `url(${projectData[boxes[activeBox].id].images[2]})`,
            backgroundSize: "cover",
            transition: "transform 0.5s linear",
            transform: animation ? "translateX(0px)" : "translateX(20px)",
          }}
        />
        <Box
          sx={{
            borderRadius: "15px",
            bgcolor: "white",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontFamily: "Lato, sans-serif",
            fontWeight: "750",
            fontSize: "15px",
            cursor: "pointer",
            transition: "transform 0.5s linear",
            transform: animation ? "translateY(0px)" : "translateY(-20px)",
            pointerEvents: "auto",
            zIndex: "100",
          }}
          onClick={() => setOpenProject(true)}
        >
          Read More
        </Box>
      </Box>
    </Box>
  );
}

export default ProjectSideDetails;
